      "key":"occurrence",
      "label":"Occurrence"
    },
    {
      "conditions": [],
      "definition":"SubjectBinding binds an external mutable subject, authority and invalidation contract; its stable binding does not replace the mutable subject W.",
      "exceptions": [],
      "grounding": [
