    },
    {
      "conditions": [],
      "definition":"OperationKind identifies an operation contract, target sort and invalidation contract. EffectOperation is a separately identified domain operation instance, with its kind, target binding, effect territory, contract and invalidation.",
      "exceptions": [],
      "grounding": [
        {
          "end_line":310,
          "quote":"| `O:EffectOperation.value.operation_kind_ref` | 1 | `O` | `OperationKind` |  | `B_model` |",
          "section_id":"repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/TRAVERSAL_OCCURRENCE.md#TRAVERSAL_OCCURRENCE%2FClosed%20semantic-object%20sorts%2FFinite%20reference-domain%20table",
