      "label":"EffectOperation and OperationKind"
    },
    {
      "conditions": [],
      "definition":"OperationGrant is an owner-issued authority grant identifying its issuer, subject binding, nonempty allowed operation-kind population, allowed territory and invalidation contract.",
      "exceptions": [],
      "grounding": [
        {
          "end_line":315,
          "quote":"| `O:OperationGrant.value.allowed_operation_kind_refs` | 1..* | `O` | `OperationKind` |  | `B_model` |",
          "section_id":"repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/TRAVERSAL_OCCURRENCE.md#TRAVERSAL_OCCURRENCE%2FClosed%20semantic-object%20sorts%2FFinite%20reference-domain%20table",
          "start_line":313
        }
