      "label":"OperationGrant"
    },
    {
      "conditions": [],
      "definition":"EffectInvocation immutably binds occurrence, operation, executor, actor, grant, territory and inputs; it contains no future disposition.",
      "exceptions": [],
      "grounding": [
        {
          "end_line":1355,
          "quote":"The\nimmutable `EffectInvocation` contains no future disposition, and\n`EffectDisposition` records the later outcome without rewriting the\ninvocation (P3, P6).",
          "section_id":"repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/TRAVERSAL_OCCURRENCE.md#TRAVERSAL_OCCURRENCE%2FMutable-subject%20effect%20relation",
          "start_line":1352
        }
      ],
      "key":"effect_invocation",
      "label":"EffectInvocation"
    },
    {
      "conditions": [],
      "definition":"EffectDisposition records the later effect outcome, optional invocation and post-observation, effect-evidence list and optional residual. EffectEvidence binds an invocation, nonempty external evidence and an observation limit.",
      "exceptions": [],
      "grounding": [
        {
          "end_line":329,
          "quote":"| `O:EffectDisposition.value.invocation_ref_or_none` | 0..1 | `O` | `EffectInvocation` |  | `B_model` |",
          "section_id":"repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/TRAVERSAL_OCCURRENCE.md#TRAVERSAL_OCCURRENCE%2FClosed%20semantic-object%20sorts%2FFinite%20reference-domain%20table",
          "start_line":323
        }
      ],
      "key":"effect_disposition",
      "label":"EffectDisposition and EffectEvidence"
    },
    {
      "conditions": [],
      "definition":"RelationClaim is a pre-admission candidate identifying relation kind, existing endpoints, claimant, claim basis, qualifiers and source frontier; constructing it does not admit it.",
      "exceptions": [],
      "grounding": [
        {
          "end_line":335,
          "quote":"| `O:RelationClaim.value.source_frontier_ref` | 1 | `O` | `EventFrontier` |  | `B_model` |",
          "section_id":"repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/TRAVERSAL_OCCURRENCE.md#TRAVERSAL_OCCURRENCE%2FClosed%20semantic-object%20sorts%2FFinite%20reference-domain%20table",
